args.command:
cat > ~/probe.py <<'EOF'
import workcell,sys,re
def st(dz):
    r=workcell.call("arm","step",str(dz)); m=re.search(r"z=([-\d.]+) mm\s+Fz=([-+\d.]+)",r.text); return float(m.group(1)),float(m.group(2))
def touch(x,y,ztop=130,zmin=60):
    workcell.call("arm","move","%f"%x,"%f"%y,"%f"%ztop)
    z=ztop
    while z>zmin:
        z,f=st(-3 if z>ztop-0 and False else -1.0)
        if f>0.3:
            st(1.0); 
            while True:
                z,f=st(-0.1)
                if f>0.3: break
            print(x,y,"touch z=%.3f F=%.2f"%(z,f)); st(3); return z
    print(x,y,"no touch above",zmin); return None
if __name__=="__main__":
    touch(float(sys.argv[1]),float(sys.argv[2]),float(sys.argv[3]),float(sys.argv[4]))
EOF
cd ~; python3 probe.py 520 -40 125 100

